/** WLAN-Router (9x7), symmetrisch um die Mittelspalte 4: zwei Antennen (Spalten 2 und 6), drei Lämpchen (2, 4, 6), `ph` lässt sie im Wechsel blinken. */
function router(ph: number): PropSprite {
  const g = grid(9, 7)
