    ...fetchIn(SCROLL),
    // aufrollen: die Hand hält die rechte Walze und ruckt, das linke Ende rollt nach links aus
    sc(1, { look: [-2, 1], t: 2 }), sc(2, { ...handTo('L', -1, 4), t: 2 }), sc(3, { ...handTo('L', -1, 5), t: 2 }),
