    ...sinkOut({ name: termName(11), size: TSIZE, at: [TX, 0], step: 2, during: { look: [-1, 0], by: 0, armL: 'down', eyes: 'open' } }),
    { look: [0, 0], armL: 'down', t: 2 },
  ],
})

