        th(end, 17, 1, { t: 2 }, [ref('work_sp3', 22, 3)]), th(end, 17, 1, { t: 2 }),
      ]),
    th(end, 17, 1, { mouth: null, by: 0, eyes: 'open' }), th(end, 17, 2), th(end, 17, 3, { t: 2 }),
    ...fetchOut({ ...TB, name: tbName(end) }),
    ...fetchIn(TB),
