    ...rep(2, [0, 1, 2, 3].map((k) => [1, { ...HAP, fy: [0, -1, -1, 0][k], armL: k === 1 || k === 2 ? A(3, -1) : A(3, 1), armR: k === 1 || k === 2 ? A(3, -1) : A(3, 1) }, HS([0, 3, 3, 0][k], 0, [0, -1, -2, -1][k])] as Beat)),
    [2, HAP, HS(3)], [2, HAP, HS(0)], [1, FL, HS(6)], [3, FL, HS(0)],
  ]),
})

