}
const wave = (y: number, k: number): PropRef => ['wait_wave' + (k % 2), -15, y, 'g'] // 12 breit, rechts bündig mit der Burg
C('limit_sandcastle', 'Baut eine Sandburg', 'limit_week', { loop: true, interruptible: true,
  intro: fetchIn(SPADE),
