  mood_z1: { rows: ['WWW', '..W', '.W.', 'W..', 'WWW'], effect: true },
  mood_z2: { rows: ['WWWWW', '....W', '...W.', '..W..', '.W...', 'W....', 'WWWWW'], effect: true },
